const raw = $input.first().json.body || $input.first().json || {};

const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();

const list = (v) => {
  if (Array.isArray(v)) return v.map(x => s(x)).filter(Boolean);
  const str = s(v);
  if (!str) return [];
  return str.split(',').map(x => x.trim()).filter(Boolean);
};

const objList = (v) => {
  if (Array.isArray(v)) return v.filter(x => x && typeof x === 'object');
  if (v && typeof v === 'object') return [v];
  return [];
};

// ---- pageType is the master switch -------------------------------------
const pageTypeRaw = s(raw.pageType).toLowerCase();
const pageType = ['industry', 'solution'].includes(pageTypeRaw) ? pageTypeRaw : '';
if (!pageType) {
  throw new Error(`pageType is required and must be "industry" or "solution". Received: "${s(raw.pageType)}"`);
}

const primaryKeyword = s(raw.primaryKeyword) || s(raw.coreKeyword);
if (!primaryKeyword) {
  throw new Error('primaryKeyword is required. Use the pattern "[category] for [industry]" for industry pages or "[category] for [use case/job]" for solution pages.');
}

// ---- the vertical / job the page is about ------------------------------
const industry = s(raw.industry);
const useCase = s(raw.useCase);
if (pageType === 'industry' && !industry) {
  throw new Error('industry is required when pageType is "industry" (e.g. "law firms", "dental clinics").');
}
if (pageType === 'solution' && !useCase) {
  throw new Error('useCase is required when pageType is "solution" (e.g. "appointment scheduling", "incident management").');
}

const clientName = s(raw.clientName);
if (!clientName) {
  throw new Error('clientName is required. Proof, CTA and quick-answer blocks cannot be written without it.');
}

// ---- structured proof: client-supplied only ----------------------------
const caseStudies = objList(raw.caseStudies).map(c => ({
  title: s(c.title),
  client: s(c.client),
  industry: s(c.industry),
  result: s(c.result),
  url: s(c.url)
})).filter(c => c.title || c.result);

const clientLogos = objList(raw.clientLogos).map(l => ({
  name: s(l.name),
  industry: s(l.industry),
  url: s(l.url)
})).filter(l => l.name);

const clientMetrics = objList(raw.clientMetrics).map(m => ({
  metric: s(m.metric),
  context: s(m.context),
  source: s(m.source)
})).filter(m => m.metric);

const testimonials = objList(raw.testimonials).map(t => ({
  quote: s(t.quote),
  author: s(t.author),
  role: s(t.role),
  company: s(t.company)
})).filter(t => t.quote);

const features = objList(raw.features).map(f => ({
  name: s(f.name),
  description: s(f.description)
})).filter(f => f.name);

const breadcrumb = objList(raw.breadcrumb).map(b => ({
  name: s(b.name),
  url: s(b.url)
})).filter(b => b.name);

const ctaObj = (v, fallbackLabel) => {
  const o = (v && typeof v === 'object') ? v : {};
  return { label: s(o.label) || fallbackLabel, url: s(o.url) };
};

return [{ json: {
  // routing / identity
  taskId: s(raw.taskId),
  brandId: s(raw.brandId),
  userId: s(raw.userId),
  callback_url: s(raw.callback_url),
  pageType,

  // keywords + language
  primaryKeyword,
  secondaryKeywords: list(raw.secondaryKeywords).join(', '),
  targetLanguage: s(raw.targetLanguage) || 'English',

  // vertical / job context
  industry,
  industryRegulations: s(raw.industryRegulations),
  industryJargon: s(raw.industryJargon),
  useCase,
  jobToBeDone: s(raw.jobToBeDone),
  adjacentTools: s(raw.adjacentTools),

  // client + product
  clientName,
  clientUrl: s(raw.clientUrl),
  productCategory: s(raw.productCategory),
  productDescription: s(raw.productDescription),
  features,
  integrations: s(raw.integrations),
  pricingModel: s(raw.pricingModel),
  implementationTime: s(raw.implementationTime),
  migrationNotes: s(raw.migrationNotes),

  // proof (client-supplied only, never invented downstream)
  caseStudies,
  clientLogos,
  certifications: list(raw.certifications),
  clientMetrics,
  testimonials,

  // conversion
  primaryCta: ctaObj(raw.primaryCta, 'Book a demo'),
  secondaryCta: ctaObj(raw.secondaryCta, ''),
  frictionStrippers: s(raw.frictionStrippers),
  ctaRules: s(raw.ctaRules),

  // page + seo scaffolding
  urlPath: s(raw.urlPath),
  breadcrumb,
  faqSeeds: list(raw.faqSeeds),
  writingPreferences: s(raw.writingPreferences),
  whitelistDomains: list(raw.whitelistDomains),
  blacklistDomains: list(raw.blacklistDomains),

  // internal linking store
  pineconeIndex: s(raw.pineconeIndex),
  pineconeNamespace: s(raw.pineconeNamespace)
} }];

const items = $input.all();

function clean(value, max = 255) {
  if (value === undefined || value === null) return '';
  return String(value).slice(0, max);
}

function makeTraceId() {
  try {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  } catch (error) {}
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const first = items[0]?.json || {};
const trace = first.trace || {};

const executionId = clean($execution.id);
const workflowId = clean($workflow.id);
const workflowName = clean($workflow.name);
const traceId = clean(trace.traceId) || makeTraceId();

const ctx = {
  createdAt: new Date().toISOString(),
  executionKey: `${workflowId}:${executionId}`,
  executionId,
  workflowId,
  workflowName,
  taskId: clean(first.taskId),
  brandId: clean(first.brandId),
  userId: clean(first.userId),
  pageType: clean(first.pageType),
  primaryKeyword: clean(first.primaryKeyword),
  traceId
};

try {
  $execution.customData.setAll({
    executionKey: ctx.executionKey,
    taskId: ctx.taskId,
    brandId: ctx.brandId,
    userId: ctx.userId,
    pageType: ctx.pageType,
    primaryKeyword: ctx.primaryKeyword,
    traceId: ctx.traceId
  });
} catch (error) {}

return [{ json: ctx }];

const items = $input.all();

function clean(value, max = 255) {
  if (value === undefined || value === null) return '';
  return String(value).slice(0, max);
}

const first = items[0]?.json || {};

const executionId = clean($execution.id);
const workflowId = clean($workflow.id);
const workflowName = clean($workflow.name);

const ctx = {
  createdAt: new Date().toISOString(),
  executionKey: `${workflowId}:${executionId}`,
  executionId,
  workflowId,
  workflowName,
  taskId: clean(first.taskId),
  brandId: clean(first.brandId),
  userId: clean(first.userId),
  pageType: clean(first.pageType),
  primaryKeyword: clean(first.primaryKeyword)
};

try {
  $execution.customData.setAll({
    executionKey: ctx.executionKey,
    taskId: ctx.taskId,
    brandId: ctx.brandId,
    userId: ctx.userId,
    pageType: ctx.pageType,
    primaryKeyword: ctx.primaryKeyword
  });
} catch (error) {}

return items.map((item) => ({
  json: { ...item.json, _ctx: { ...(item.json._ctx || {}), ...ctx } },
  binary: item.binary
}));

const j = $input.first().json;

const pageType = String(j.pageType || '').toLowerCase().trim();
const lang = String(j.targetLanguage || '').toLowerCase().trim();
const isEnglish = !lang || lang.startsWith('english');

const route = `${pageType}_${isEnglish ? 'en' : 'lang'}`;

return [{ json: { ...j, route, isIndustry: pageType === 'industry', isSolution: pageType === 'solution', isLang: !isEnglish } }];

const route = $('Route Classifier').first().json.route;
const brief = $('Brief Parser').first().json;
const j = $input.first().json;

const tr = {};
if (j.translations) {
  const names = $('DeepL Prep').first().json.fieldNames;
  if (!Array.isArray(j.translations) || j.translations.length !== names.length) {
    throw new Error(`DeepL returned ${j.translations?.length} translations but expected ${names.length}`);
  }
  names.forEach((n, i) => { tr[n] = j.translations[i].text; });
}

const pick = (k) => tr[k] ?? (brief[k] || '');

return [{ json: {
  ...brief,
  route,
  isIndustry: route.startsWith('industry'),
  isSolution: route.startsWith('solution'),
  isLang: route.endsWith('_lang'),

  // originals are kept so the H1 / keyword can be restored in the target language
  originalPrimaryKeyword: brief.primaryKeyword,
  originalSecondaryKeywords: brief.secondaryKeywords,

  primaryKeyword:      pick('primaryKeyword'),
  secondaryKeywords:   pick('secondaryKeywords'),
  industry:            pick('industry'),
  industryRegulations: pick('industryRegulations'),
  industryJargon:      pick('industryJargon'),
  useCase:             pick('useCase'),
  jobToBeDone:         pick('jobToBeDone'),
  adjacentTools:       pick('adjacentTools'),
  productCategory:     pick('productCategory'),
  productDescription:  pick('productDescription'),
  featuresText:        pick('featuresText'),
  integrations:        pick('integrations'),
  pricingModel:        pick('pricingModel'),
  implementationTime:  pick('implementationTime'),
  migrationNotes:      pick('migrationNotes'),
  proofText:           pick('proofText'),
  primaryCtaLabel:     pick('primaryCtaLabel'),
  secondaryCtaLabel:   pick('secondaryCtaLabel'),
  frictionStrippers:   pick('frictionStrippers'),
  ctaRules:            pick('ctaRules'),
  faqSeedsText:        pick('faqSeedsText'),
  writingPreferences:  pick('writingPreferences')
} }];

