const raw = $input.first().json.output || $input.first().json;

let bp;
if (typeof raw === 'string') {
  bp = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} else {
  bp = raw;
}

if (!bp || !Array.isArray(bp.h2Plan) || bp.h2Plan.length === 0) {
  throw new Error('Page Architect returned no h2Plan. Cannot draft a page without an outline.');
}

let outline = '';
for (const s of bp.h2Plan) {
  outline += `## ${s.h2_title}\n[block: ${s.block || 'context'}]\n${s.h2_description || ''}\n\n`;
  if (Array.isArray(s.subsections)) {
    for (const sub of s.subsections) {
      outline += `### ${sub.h3_title}\n${sub.h3_description || ''}\n\n`;
    }
  }
}

const qa = bp.quickAnswer || {};
const quickAnswerBrief = [
  qa.whatItIs ? `What it is: ${qa.whatItIs}` : '',
  qa.whoItIsFor ? `Who it is for: ${qa.whoItIsFor}` : '',
  Array.isArray(qa.capabilities) && qa.capabilities.length ? `Concrete capabilities: ${qa.capabilities.join('; ')}` : '',
  qa.keyFact ? `Key compliance or outcome fact: ${qa.keyFact}` : ''
].filter(Boolean).join('\n');

const painBrief = (bp.painPoints || []).map((p, i) =>
  `${i + 1}. ${p.title}\n   ${p.description || ''}\n   Vocabulary to use: ${(p.verticalVocabulary || []).join(', ') || 'n/a'}\n   Source: ${p.sourceUrl || 'none - do not make a factual claim here'}`
).join('\n');

const solutionBrief = (bp.solutionMapping || []).map((m, i) =>
  `${i + 1}. ${m.feature} -> ${m.outcome}\n   Written for: ${m.audienceLayer || 'user'}\n   Product visual: ${m.visualHint || 'n/a'}`
).join('\n');

const faqBrief = (bp.faq || []).map((f, i) =>
  `${i + 1}. ${f.question}\n   Answer angle: ${f.answerAngle || ''}\n   Fan-out category: ${f.fanoutCategory || ''}`
).join('\n');

const proof = bp.proofPlan || {};
const proofBrief = [
  (proof.useMetrics || []).length ? `Client metrics to use verbatim: ${(proof.useMetrics || []).join(' | ')}` : '',
  (proof.useCaseStudies || []).length ? `Case studies to reference: ${(proof.useCaseStudies || []).join(' | ')}` : '',
  (proof.surfaceCertifications || []).length ? `Certifications to surface: ${(proof.surfaceCertifications || []).join(', ')}` : '',
  proof.note || ''
].filter(Boolean).join('\n') || 'No client proof available. Render certifications and testimonials only if present, otherwise keep the block short and factual. Never invent a number.';

const cta = bp.ctaPlan || {};

return [{ json: {
  pageDescription: bp.pageDescription || '',
  confirmedPrimaryKeyword: bp.confirmedPrimaryKeyword || '',
  blueprintSecondaryKeywords: Array.isArray(bp.secondaryKeywords) ? bp.secondaryKeywords.join(', ') : String(bp.secondaryKeywords || ''),
  outlineFormatted: outline.trim(),
  quickAnswerBrief,
  painBrief,
  solutionBrief,
  faqBrief,
  proofBrief,
  ctaBrief: [
    cta.primary ? `Primary CTA: ${cta.primary}` : '',
    cta.secondary ? `Lower-commitment CTA: ${cta.secondary}` : '',
    cta.frictionStrippers ? `Friction strippers: ${cta.frictionStrippers}` : ''
  ].filter(Boolean).join('\n'),
  blueprintRaw: bp
} }];

