const item = $input.first();
const text = (item.json?.finalPage || '').trim();

if (!text) return $input.all();

const cleaned = text
  .replace(/\["([^\]]+)"\]/g, '[$1]')
  .replace(/\['([^\]]+)'\]/g, '[$1]')
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .replace(/\t/g, ' ');

return [{ json: {
  cleanedPage: cleaned,
  primaryKeyword: item.json?.primaryKeyword || '',
  secondaryKeywords: item.json?.secondaryKeywords || ''
} }];

function parseInlineText(text) {
  const children = [];
  const regex = /\*\*([^*]+)\*\*|\*([^*]+)\*|\[([^\]\n]+)\]\((https?:\/\/[^)\s]+)\)/g;
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      children.push({ type: 'text', text: text.substring(lastIndex, match.index) });
    }
    const [, boldText, italicText, linkText, linkUrl] = match;
    if (boldText !== undefined) {
      children.push({ type: 'text', text: boldText, bold: true });
    } else if (italicText !== undefined) {
      children.push({ type: 'text', text: italicText, italic: true });
    } else if (linkText !== undefined && linkUrl !== undefined) {
      children.push({
        type: 'link',
        url: linkUrl.split('?utm_source=openai')[0],
        children: [{ type: 'text', text: linkText }]
      });
    }
    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    children.push({ type: 'text', text: text.substring(lastIndex) });
  }
  if (children.length === 0 && text) {
    children.push({ type: 'text', text: text });
  }
  return children;
}

function markdownToStrapi(text) {
  const lines = text.split('\n');
  let h1Title = "";
  const introduction = [];
  const h2Headings = [];
  let headingIdCounter = 1;
  let currentH2 = null, currentH3 = null, currentH4 = null;

  const getTargetBody = () => currentH4?.bodyText || currentH3?.bodyText || currentH2?.bodyText || introduction;

  for (let i = 0; i < lines.length; i++) {
    const trimmedLine = lines[i].trim();
    if (trimmedLine === "") continue;

    const headingMatch = trimmedLine.match(/^(#{1,4}) (.+)$/);
    if (headingMatch) {
      const level = headingMatch[1].length;
      const headingText = headingMatch[2].trim();
      switch (level) {
        case 1:
          h1Title = headingText;
          currentH2 = currentH3 = currentH4 = null;
          break;
        case 2:
          currentH2 = { h2Heading: headingText, headingId: headingIdCounter++, bodyText: [], h3Headings: [] };
          h2Headings.push(currentH2);
          currentH3 = currentH4 = null;
          break;
        case 3:
          if (currentH2) {
            currentH3 = { h3Heading: headingText, headingId: headingIdCounter++, bodyText: [], h4Headings: [] };
            currentH2.h3Headings.push(currentH3);
            currentH4 = null;
          } else {
            getTargetBody().push({ type: 'paragraph', children: parseInlineText(trimmedLine) });
          }
          break;
        case 4:
          if (currentH3) {
            currentH4 = { h4Heading: headingText, headingId: headingIdCounter++, bodyText: [] };
            currentH3.h4Headings.push(currentH4);
          } else {
            getTargetBody().push({ type: 'paragraph', children: parseInlineText(trimmedLine) });
          }
          break;
      }
      continue;
    }

    if (trimmedLine.startsWith('- ')) {
      const targetBody = getTargetBody();
      const lastElement = targetBody[targetBody.length - 1];
      if (lastElement?.type === 'list') {
        lastElement.children.push({ type: 'list-item', children: parseInlineText(trimmedLine.substring(2)) });
      } else {
        targetBody.push({ type: 'list', format: 'unordered', children: [{ type: 'list-item', children: parseInlineText(trimmedLine.substring(2)) }] });
      }
      continue;
    }

    getTargetBody().push({ type: 'paragraph', children: parseInlineText(trimmedLine) });
  }

  return { title: h1Title, h1Title, introduction, h2Headings };
}

try {
  const item = $input.first();
  const markdownInputText = (item.json?.cleanedPage || '').trim();

  if (!markdownInputText) return $input.all();

  const parsedData = markdownToStrapi(markdownInputText);

  const secondaryKeywords = typeof item.json?.secondaryKeywords === 'string'
    ? item.json.secondaryKeywords.split(',').map(k => k.trim()).filter(k => k)
    : (Array.isArray(item.json?.secondaryKeywords) ? item.json.secondaryKeywords : []);

  return [{ json: { result: {
    ...parsedData,
    primaryKeyword: item.json?.primaryKeyword || '',
    secondaryKeywords
  }}}];

} catch (error) {
  return [{ json: { error: error.message, stack: error.stack } }];
}

