// Builds the one JSON-LD graph the research calls non-negotiable:
// Organization + Service + FAQPage + BreadcrumbList.
// Nothing here is generated by a model: every value comes from client intake
// or from parsing the page that was already written.

const req = $('request-parser').first().json;
const brief = $('Brief EN').first().json;
const page = $('Final Page').first().json.finalPage || '';
const meta = $input.first().json.output || $input.first().json || {};

const h1 = (page.match(/^#\s+(.+)$/m) || [])[1] || '';

// ---- parse the FAQ block ------------------------------------------------
// Language-agnostic: group H3s under their H2, then take the group where most
// H3 titles end in a question mark. Covers Latin, Greek and Arabic marks.
const QMARK = /[?？;؟]\s*$/;
const lines = page.split('\n');

const groups = [];
let current = null;
let pendingH3 = null;

const pushH3 = () => {
  if (pendingH3 && current) {
    current.items.push({ question: pendingH3.title, answer: pendingH3.body.join(' ').trim() });
  }
  pendingH3 = null;
};

for (const raw of lines) {
  const line = raw.trim();
  const h2 = line.match(/^##\s+(.+)$/);
  const h3 = line.match(/^###\s+(.+)$/);

  if (h2) { pushH3(); current = { h2: h2[1].trim(), items: [] }; groups.push(current); continue; }
  if (h3) { pushH3(); pendingH3 = { title: h3[1].trim(), body: [] }; continue; }
  if (line.startsWith('#')) { pushH3(); continue; }
  if (!line) continue;
  if (pendingH3) pendingH3.body.push(line.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1'));
}
pushH3();

let faq = [];
let bestScore = 0;
for (const g of groups) {
  if (g.items.length < 3) continue;
  const questionish = g.items.filter(i => QMARK.test(i.question)).length;
  const ratio = questionish / g.items.length;
  if (ratio >= 0.6 && questionish > bestScore) { bestScore = questionish; faq = g.items; }
}
faq = faq.filter(f => f.question && f.answer);

// ---- breadcrumb ---------------------------------------------------------
const origin = (() => {
  try { return new URL(req.clientUrl).origin; } catch (e) { return String(req.clientUrl || '').replace(/\/+$/, ''); }
})();

const abs = (u) => {
  if (!u) return '';
  if (/^https?:\/\//i.test(u)) return u;
  return origin ? origin + (u.startsWith('/') ? u : '/' + u) : u;
};

const slug = String(meta.url_slug || '').replace(/^\/+|\/+$/g, '');
const pageUrl = req.urlPath ? abs(req.urlPath) : (origin && slug ? `${origin}/${slug}` : origin);

const crumbs = [...(req.breadcrumb || [])];
if (!crumbs.length && origin) crumbs.push({ name: 'Home', url: origin });
crumbs.push({ name: h1 || meta.meta_title || '', url: pageUrl });

const breadcrumbList = {
  '@type': 'BreadcrumbList',
  itemListElement: crumbs.filter(c => c.name).map((c, i) => ({
    '@type': 'ListItem',
    position: i + 1,
    name: c.name,
    item: abs(c.url)
  }))
};

// ---- organization -------------------------------------------------------
const organization = {
  '@type': 'Organization',
  '@id': origin ? `${origin}/#organization` : undefined,
  name: req.clientName,
  url: req.clientUrl || undefined,
  description: req.productDescription || undefined
};
if ((req.certifications || []).length) {
  organization.hasCredential = req.certifications.map(c => ({
    '@type': 'EducationalOccupationalCredential',
    credentialCategory: 'certification',
    name: c
  }));
}
Object.keys(organization).forEach(k => organization[k] === undefined && delete organization[k]);

// ---- service ------------------------------------------------------------
const service = {
  '@type': 'Service',
  '@id': pageUrl ? `${pageUrl}#service` : undefined,
  name: h1 || brief.primaryKeyword,
  serviceType: req.productCategory || undefined,
  description: meta.meta_description || undefined,
  url: pageUrl || undefined,
  provider: organization['@id'] ? { '@id': organization['@id'] } : { '@type': 'Organization', name: req.clientName },
  inLanguage: brief.targetSource
};
if (req.pageType === 'industry' && req.industry) {
  service.audience = { '@type': 'BusinessAudience', name: req.industry };
}
if (req.pageType === 'solution' && (req.useCase || req.jobToBeDone)) {
  service.category = req.useCase || req.jobToBeDone;
}
Object.keys(service).forEach(k => service[k] === undefined && delete service[k]);

// ---- faq page -----------------------------------------------------------
const graph = [organization, service, breadcrumbList];
if (faq.length) {
  graph.push({
    '@type': 'FAQPage',
    '@id': pageUrl ? `${pageUrl}#faq` : undefined,
    mainEntity: faq.map(f => ({
      '@type': 'Question',
      name: f.question,
      acceptedAnswer: { '@type': 'Answer', text: f.answer }
    }))
  });
}

const schemaJsonLd = { '@context': 'https://schema.org', '@graph': graph };

return [{ json: {
  schemaJsonLd,
  faq,
  faqCount: faq.length,
  h1,
  pageUrl,
  slug,
  metaTitle: meta.meta_title || '',
  metaDescription: meta.meta_description || '',
  lastUpdated: new Date().toISOString().slice(0, 10)
} }];
